    family_id = data.get('family_id')
    if family_id not in state['families']:
        abort(404, 'family not found')
    child_id = new_id('child')
    child = {
        'id': child_id,
        'family_id': family_id,
        'name': data.get('name'),
        'dob': data.get('dob'),
        'classroom_id': None,
        'waitlisted': False,
        'immunization_status': data.get('immunization_status', 'missing'),
        'allergy_alerts': data.get('allergy_alerts', []),
        'pickup_authorities': data.get('pickup_authorities', []),
        'notes': data.get('notes', ''),
        'compliant': data.get('immunization_status', 'missing') in {'current', 'exempt'},
        'created_at': now(),
        'updated_at': now(),
    }
    state['children'][child_id] = child
    state['families'][family_id]['children'].append(child_id)
    return jsonify(child), 201


@app.get('/children')
def list_children():
    return jsonify(list(state['children'].values()))


@app.post('/classrooms')
def create_classroom():
    data = request.get_json(force=True)
    classroom_id = new_id('cls')
    classroom = {
        'id': classroom_id,
        'name': data.get('name'),
        'site': data.get('site', 'default'),
        'room_type': data.get('room_type', 'general'),
        'capacity': int(data.get('capacity', 0)),
        'children': [],
    }
    state['classrooms'][classroom_id] = classroom
    return jsonify(classroom), 201


@app.get('/classrooms')
def list_classrooms():
    classrooms = []
    for c in state['classrooms'].values():
        classrooms.append({**c, 'enrolled_count': len(c['children']), 'available': len(c['children']) < c['capacity']})
    return jsonify(classrooms)


@app.post('/enroll')
def enroll_child():
    data = request.get_json(force=True)
    child_id = data.get('child_id')
    classroom_id = data.get('classroom_id')
    child = state['children'].get(child_id)
    classroom = state['classrooms'].get(classroom_id)
    if not child or not classroom:
        abort(404, 'child or classroom not found')
    if len(classroom['children']) >= classroom['capacity'] and not data.get('override', False):
        child['waitlisted'] = True
        state['waitlist'].append({'child_id': child_id, 'classroom_id': classroom_id, 'created_at': now()})
        return jsonify({'status': 'waitlisted', 'child_id': child_id, 'classroom_id': classroom_id}), 409
    if child['classroom_id'] and child['classroom_id'] in state['classrooms']:
        old = state['classrooms'][child['classroom_id']]
        if child_id in old['children']:
            old['children'].remove(child_id)
    child['classroom_id'] = classroom_id
    child['waitlisted'] = False
    child['updated_at'] = now()
    if child_id not in classroom['children']:
        classroom['children'].append(child_id)
    return jsonify({'status': 'enrolled', 'child_id': child_id, 'classroom_id': classroom_id})


@app.post('/attendance/check-in')
def check_in():
    data = request.get_json(force=True)
    child_id = data.get('child_id')
    if child_id not in state['children']:
        abort(404, 'child not found')
    record = {'child_id': child_id, 'action': 'check-in', 'time': now()}
    state['attendance'].append(record)
    return jsonify(record), 201


@app.post('/attendance/check-out')
def check_out():
    data = request.get_json(force=True)
    child_id = data.get('child_id')
    if child_id not in state['children']:
        abort(404, 'child not found')
    child = state['children'][child_id]
    if any(a['child_id'] == child_id and a['action'] == 'check-in' for a in state['attendance']):
        record = {'child_id': child_id, 'action': 'check-out', 'time': now()}
        state['attendance'].append(record)
        return jsonify(record), 201
    abort(400, 'child has not been checked in')


@app.get('/attendance')
def attendance_report():
    return jsonify(state['attendance'])


@app.post('/invoices')
def create_invoice():
    data = request.get_json(force=True)
    invoice_id = new_id('inv')
    invoice = {
        'id': invoice_id,
        'family_id': data.get('family_id'),
        'child_id': data.get('child_id'),
        'amount': float(data.get('amount', 0)),
        'balance': float(data.get('amount', 0)),
        'status': 'open',
        'adjustments': [],
        'payments': [],
    }
    state['invoices'][invoice_id] = invoice
    return jsonify(invoice), 201


@app.get('/invoices')
def list_invoices():
    return jsonify(list(state['invoices'].values()))


@app.post('/payments')
def make_payment():
    data = request.get_json(force=True)
    invoice = state['invoices'].get(data.get('invoice_id'))
    if not invoice:
        abort(404, 'invoice not found')
    amount = float(data.get('amount', 0))
    payment = {
        'id': new_id('pay'),
        'invoice_id': invoice['id'],
        'payer': data.get('payer'),
        'amount': amount,
        'status': 'failed' if data.get('fail') else 'completed',
        'time': now(),
    }
    state['payments'].append(payment)
    if payment['status'] == 'failed':
        return jsonify(payment), 402
    invoice['balance'] = max(0.0, invoice['balance'] - amount)
    invoice['payments'].append(payment['id'])
    if invoice['balance'] == 0:
        invoice['status'] = 'paid'
    return jsonify(payment), 201


@app.get('/reports/summary')
def summary_report():
    return jsonify({
        'families': len(state['families']),
        'children': len(state['children']),
        'classrooms': len(state['classrooms']),
        'waitlist': len(state['waitlist']),
        'invoices': len(state['invoices']),
        'payments': len(state['payments']),
        'attendance_events': len(state['attendance']),
    })


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8000)
EOF

